-- Function: public.fn_get_intelligence_curriculum_variety
-- Backup generated on 2026-10-25 20:33:25

CREATE OR REPLACE FUNCTION public.fn_get_intelligence_curriculum_variety(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid, p_classroom_id uuid, p_start_date date, p_end_date date)  RETURNS TABLE(title character varying, usage_count bigint)  LANGUAGE sql  STABLE AS $function$     SELECT          e.title AS title,         COUNT(es.id) AS usage_count     FROM experience_schedules es     JOIN experiences e ON es.experience_id = e.id     JOIN classrooms cl ON es.classroom_id = cl.id     JOIN branches b ON cl.branch_id = b.id     WHERE es.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND (p_branch_id IS NULL OR b.id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)       AND es.scheduled_date BETWEEN p_start_date AND p_end_date     GROUP BY e.title     ORDER BY usage_count DESC; $function$ ;
